//lxrtxdy!
#pragma GCC optimize(3)
#include <bits/stdc++.h>
#define MAX_SIZE 7100
typedef long long ll;
#define INF 1000000000
using namespace std;

class DinicFlow {
public:
    struct Edge {
        int from, to;
        ll flow, cap;
    };
    int S, T;
    vector<Edge> edges;
    vector<int> adj[MAX_SIZE];
    int level[MAX_SIZE], vis[MAX_SIZE];
    int ptr[MAX_SIZE];

    void init() {
        edges.clear();
        for (int i = 0; i < MAX_SIZE; i++) adj[i].clear();
    }

    void addEdge(int u, int v, ll cap) {
        edges.push_back({u, v, 0, cap});
        edges.push_back({v, u, 0, 0});
        adj[u].push_back((int)edges.size() - 2);
        adj[v].push_back((int)edges.size() - 1);
    }

    bool bfs() {
        memset(vis, 0, sizeof(vis));
        memset(level, 0, sizeof(level));
        queue<int> q;
        q.push(S);
        vis[S] = 1;
        level[S] = 0;
        while (!q.empty()) {
            int v = q.front(); q.pop();
            for (int idx : adj[v]) {
                Edge &e = edges[idx];
                if (!vis[e.to] && e.cap > e.flow) {
                    level[e.to] = level[v] + 1;
                    q.push(e.to);
                    vis[e.to] = 1;
                }
            }
        }
        return vis[T];
    }

    ll dfs(int v, ll flow) {
        if (v == T || flow == 0) return flow;
        ll pushed = 0, add;
        for (int &i = ptr[v]; i < (int)adj[v].size(); i++) {
            Edge &e = edges[adj[v][i]];
            if (level[v] + 1 == level[e.to]) {
                ll minf = min(flow, e.cap - e.flow);
                add = dfs(e.to, minf);
                if (add > 0) {
                    e.flow += add;
                    edges[adj[v][i] ^ 1].flow -= add;
                    pushed += add;
                    flow -= add;
                    if (flow == 0) break;
                }
            }
        }
        return pushed;
    }

    ll maxFlow() {
        ll flow = 0;
        while (bfs()) {
            memset(ptr, 0, sizeof(ptr));
            flow += dfs(S, INF);
        }
        return flow;
    }
};

DinicFlow mf;
char g1[14][14];
char g2[14][14];
bool seen[14][14];
int d[14][14];
int n;
int tgt[103];

void BFS(int sx, int sy) {
    queue<pair<pair<int, int>, int>> q;
    for (int i = 0; i < 14; i++)
        for (int j = 0; j < 14; j++)
            d[i][j] = 111;
    d[sx][sy] = 0;
    q.push({{sx, sy}, 0});
    int dx[4] = {1, 0, 0, -1}, dy[4] = {0, 1, -1, 0};
    while (!q.empty()) {
        auto cur = q.front(); q.pop();
        int cx = cur.first.first, cy = cur.first.second;
        if (seen[cx][cy]) continue;
        seen[cx][cy] = true;
        d[cx][cy] = cur.second;
        for (int i = 0; i < 4; i++) {
            int nx = cx + dx[i], ny = cy + dy[i];
            if (nx < 1 || nx > n || ny < 1 || ny > n || seen[nx][ny] || g1[nx][ny] == 'Y') continue;
            q.push({{nx, ny}, cur.second + 1});
        }
    }
}

int idx(int l, int x, int y) {
    return l * n * n + (x - 1) * n + y;
}

int main() {
    int i, j, k, t;
    scanf("%d%d", &n, &t);
    for (i = 1; i <= n; i++) scanf("%s", g1[i] + 1);
    for (i = 1; i <= n; i++) scanf("%s", g2[i] + 1);

    mf.S = 0;
    mf.T = MAX_SIZE - 2;
    int sx = 0, sy = 0;
    for (i = 1; i <= n; i++) {
        for (j = 1; j <= n; j++) {
            if (g1[i][j] == 'Z') {
                sx = i; sy = j;
                break;
            }
        }
        if (sx) break;
    }

    for (i = 1; i <= n * n; i++) tgt[i] = MAX_SIZE - 3 - (n * n - i);

    BFS(sx, sy);

    for (i = 1; i <= n; i++) {
        for (j = 1; j <= n; j++) {
            if (g1[i][j] >= '0' && g1[i][j] <= '9')
                mf.addEdge(mf.S, idx(0, i, j), g1[i][j] - '0');
            if (g2[i][j] >= '0' && g2[i][j] <= '9')
                mf.addEdge(tgt[idx(0, i, j)], mf.T, g2[i][j] - '0');
            mf.addEdge(idx(0, i, j), tgt[idx(0, i, j)], INF);
        }
    }

    int dx[4] = {1, 0, 0, -1}, dy[4] = {0, 1, -1, 0};
    for (i = 1; i <= t; i++) {
        for (j = 1; j <= n; j++) {
            for (k = 1; k <= n; k++) {
                if (g1[j][k] == 'Y' || g1[j][k] == 'Z') continue;
                for (int l = 0; l < 4; l++) {
                    int tx = dx[l] + j, ty = dy[l] + k;
                    if (tx >= 1 && tx <= n && ty >= 1 && ty <= n && g1[tx][ty] != 'Y' && g1[tx][ty] != 'Z') {
                        if (d[j][k] >= i && d[tx][ty] >= i && g1[j][k] != 'Y' && g1[j][k] != 'Z') {
                            mf.addEdge(idx(i-1, tx, ty), idx(i, j, k), INF);
                        }
                    }
                }
                mf.addEdge(idx(i, j, k), tgt[idx(0, j, k)], INF);
            }
        }
    }
    printf("%lld\n", mf.maxFlow());
    return 0;
}
